<script>
    const MODULES=[
      {title:"Module 1 - Raw Material Organisation & Technical Information",items:["How to choose your raw material palette and set up your perfume organ","Overview of the raw-material technical documents needed from suppliers","Build your technical files; the technical information for each ingredient"]},
      {title:"Module 2 - Formula Composition Skills",items:["The major methods to build a formula","Which method is the perfect fit for your project","Formula evaluation, revision and adjustments","Sampling trials: codes and labelling, packaging"]},
      {title:"Module 3 - Formula Technical Skills",items:["Create your formula Excel sheets: ratio, density, different pricing, INCI names","How to translate your formula into a production sheet","Formula samples coding & labelling"]},
      {title:"Module 4 - Formula Pricing",items:["How to create a cost-efficiency formula","The major mistakes to avoid"]},
    ];
    let openIdx=0;
    function renderAcc(){
      document.getElementById('accordion').innerHTML=MODULES.map((m,i)=>`
        <div class="border-b" style="border-color:rgba(11,65,49,.15);">
          <button onclick="openIdx=${openIdx===i?-1:i};renderAcc();" class="w-full flex items-center justify-between gap-4 text-white px-5 sm:px-6 py-5 text-left" style="background:var(--green-primary);">
            <span class="font-serif text-lg sm:text-xl lg:text-2xl">${m.title}</span>
            <svg class="shrink-0" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" style="transition:transform .3s;transform:rotate(${openIdx===i?180:0}deg)"><path d="M6 9l6 6 6-6"/></svg>
          </button>
          ${openIdx===i?`<div class="bg-white px-5 sm:px-6 lg:px-10 py-7"><ul class="space-y-3 text-[17px] sm:text-[18px] leading-relaxed" style="color:var(--text-dark);">${m.items.map(it=>`<li class="flex gap-3"><span style="color:var(--soft-sage);">&#9670;</span><span>${it}</span></li>`).join('')}</ul></div>`:''}
        </div>`).join('');
    }
    renderAcc();
    
  </script>

